def collect(item, items=None):
    if items is None:
        items = []
    items.append(item)
    return items[:]

head_files.module.py:
def collect(item, items=[]):
    if items is None:
        items = list()
    items.append(item)
    return list(items)

def lookup(connection, name):
    query = 'SELECT id FROM users WHERE name = ?'
    cursor = connection.execute(query.replace('?', "'" + name + "'"))
    return cursor.fetchall()

